/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* The recognition results below are pre-rendered to speech on the
 * development host with espeak-ng and embedded here as 16-bit mono PCM at
 * TTS_SAMPLE_RATE.  This keeps the example free of any runtime TTS engine
 * dependency while still letting the recognized text actually be spoken.
 */

#define TTS_SAMPLE_RATE   11025  /* embedded speech sample rate (Hz) */
#define TTS_CHANNELS      1      /* mono                               */
#define TTS_BPS           16     /* bits per sample                    */

#define WAV_PATH          "/data/tts_result.wav"
#define NXPLAYER_CMD      "/data/nxplayer.cmd"

/* Virtual camera (registered by the qemu board).  We grab one QVGA RGB565
 * frame per recognition so the "image" really comes from the camera device.
 */

#define CAMERA_DEV_PATH   "/dev/video"
#define CAM_WIDTH         320
#define CAM_HEIGHT        240
#define CAM_FRAME_SIZE    (CAM_WIDTH * CAM_HEIGHT * 2)

/****************************************************************************
 * Private Data
 ****************************************************************************/

